<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\Theme\Domain\ValueObject;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFail;

class ThemeVersionVO
{
  public static function empty(): ThemeVersionVO
  {
      return new ThemeVersionVO(null);
  }
  public static function from(ThemeVersionVO|int|null $value): ThemeVersionVO
  {
    return self::fromUnsafe($value);
  }
  public static function tryFrom(mixed $value, ConstraintFailList $list): ?ThemeVersionVO
  {
    if ( $value instanceof ThemeVersionVO ) {
      // If is a ValueObject, its already validated... nothing to append
      return $value;
    } else if( !$value ) {
      return new ThemeVersionVO($value);
    } else if( is_integer($value)) {
      return new ThemeVersionVO($value);
    } else {
      $list->add(new ConstraintFail('wrong_type', ['version'], [$value], ['int']));
      return null;
    }
  }
  private static function fromUnsafe(mixed $value): ThemeVersionVO
  {
    if ($value instanceof ThemeVersionVO) {
      // If is a ValueObject, its already validated
      return $value;
    } else {
      // If is not a ValueObject, validation is need and exception throw
      $errorsList = new ConstraintFailList();
      $candidate = self::tryFrom($value, $errorsList);
      if ($errorsList->hasErrors()) {
        throw $errorsList->asConstraintException();
      }
      \assert($candidate instanceof ThemeVersionVO);
      return $candidate;
    }
  }
  /**
   * private constructor to avoid build a value without all the rule validations.
   */
  private function __construct(
    private readonly ?int $version
  ) {
  }
  public function value(): ?int
  {
    return $this->version;
  }
  public function equals(?ThemeVersionVO $other): bool
  {
    return $this->value() == $other?->value();
  }
}
